import json
from itertools import permutations

def solve():
    houses = [1, 2, 3, 4]

    names = ["Alice", "Peter", "Arnold", "Eric"]
    cigars = ["prince", "dunhill", "blue master", "pall mall"]
    sports = ["swimming", "basketball", "soccer", "tennis"]
    drinks = ["coffee", "water", "milk", "tea"]

    solutions = []

    for perm_name in permutations(names):
        # Clue 1: Peter is in the fourth house.
        if perm_name[3] != "Peter":
            continue

        for perm_cigar in permutations(cigars):
            # Clue 10: Peter is the person partial to Pall Mall.
            if perm_cigar[3] != "pall mall":
                continue

            # Clue 3: Arnold is the person who smokes Blue Master.
            try:
                if perm_cigar[perm_name.index("Arnold")] != "blue master":
                    continue
            except ValueError:
                continue

            for perm_sport in permutations(sports):
                # Clue 8: The person who loves basketball is in the third house.
                if perm_sport[2] != "basketball":
                    continue

                # Clue 4: The person who loves basketball is Eric.
                if perm_name[2] != "Eric":
                    continue

                # Clue 5: The person who loves tennis is the person who smokes Blue Master.
                if perm_sport.index("tennis") != perm_cigar.index("blue master"):
                    continue

                # Clue 9: The Prince smoker is the person who loves soccer.
                if perm_cigar.index("prince") != perm_sport.index("soccer"):
                    continue

                for perm_drink in permutations(drinks):
                    # Clue 2: The tea drinker is the person who loves basketball.
                    if perm_drink.index("tea") != perm_sport.index("basketball"):
                        continue

                    # Clue 7: The coffee drinker is Arnold.
                    if perm_drink.index("coffee") != perm_name.index("Arnold"):
                        continue

                    # Clue 6: There are two houses between the one who only drinks water and Peter.
                    if abs(perm_drink.index("water") - perm_name.index("Peter")) != 3:
                        continue

                    # Construct a solution
                    sol_rows = []
                    for i in range(4):
                        sol_rows.append([
                            str(houses[i]),
                            perm_name[i],
                            perm_cigar[i],
                            perm_sport[i],
                            perm_drink[i],
                        ])
                    solutions.append(sol_rows)

    # Assuming unique solution
    if not solutions:
        raise RuntimeError("No solution found.")
    result = {
        "solution": {
            "header": ["House", "Name", "cigar", "sports", "drink"],
            "rows": solutions[0]
        }
    }
    return result

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
